-- 테스트(H2) 전용: Hibernate가 엔티티로 테이블을 만든 뒤 실행해요. 시퀀스는 엔티티가 없어서 직접 만들어요(schema.sql v0.3.7과 같게).
CREATE SEQUENCE IF NOT EXISTS stop_group_seq START WITH 1;
-- equipment_signal은 엔티티가 없어서(백엔드는 읽기만) 직접 만들어요 (schema.sql v0.3.5와 같게)
CREATE TABLE IF NOT EXISTS equipment_signal (equipment_id VARCHAR(20) PRIMARY KEY, last_seen_at TIMESTAMP NOT NULL, fault SMALLINT NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- product_flow도 엔티티가 없어서(백엔드는 읽기만) 직접 만들어요 (schema.sql v0.3.9와 같게)
CREATE TABLE IF NOT EXISTS product_flow (flow_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id VARCHAR(30) NOT NULL, equipment_id VARCHAR(20) NOT NULL, line_id VARCHAR(5) NOT NULL, started_at TIMESTAMP, ended_at TIMESTAMP, UNIQUE (product_id, equipment_id));
